PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users (
 id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE COLLATE NOCASE,
 phone TEXT NOT NULL, birth_date TEXT, password_hash TEXT NOT NULL,
 role TEXT NOT NULL CHECK(role IN ('elder','caregiver')), demo_group TEXT,
 consent_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS patients (id TEXT PRIMARY KEY,user_id TEXT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS links (patient_id TEXT NOT NULL REFERENCES patients(id) ON DELETE CASCADE,caregiver_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(patient_id,caregiver_id));
CREATE TABLE IF NOT EXISTS invites (code_hash TEXT PRIMARY KEY,patient_id TEXT NOT NULL REFERENCES patients(id) ON DELETE CASCADE,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS medications (id TEXT PRIMARY KEY,patient_id TEXT NOT NULL REFERENCES patients(id) ON DELETE CASCADE,name TEXT NOT NULL,dosage TEXT NOT NULL,time TEXT NOT NULL,instructions TEXT NOT NULL DEFAULT '',version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS confirmations (id TEXT PRIMARY KEY,patient_id TEXT NOT NULL REFERENCES patients(id) ON DELETE CASCADE,medication_id TEXT NOT NULL REFERENCES medications(id) ON DELETE CASCADE,day TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('taken','not_taken','snoozed')),snooze_until TEXT,actor_id TEXT REFERENCES users(id) ON DELETE SET NULL,created_at TEXT NOT NULL,UNIQUE(medication_id,day));
CREATE TABLE IF NOT EXISTS appointments (id TEXT PRIMARY KEY,patient_id TEXT NOT NULL REFERENCES patients(id) ON DELETE CASCADE,doctor TEXT NOT NULL,specialty TEXT NOT NULL,date TEXT NOT NULL,time TEXT NOT NULL,location TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '',version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS contacts (id TEXT PRIMARY KEY,patient_id TEXT NOT NULL REFERENCES patients(id) ON DELETE CASCADE,name TEXT NOT NULL,phone TEXT NOT NULL,relationship TEXT NOT NULL,notify INTEGER NOT NULL DEFAULT 1,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS alerts (id TEXT PRIMARY KEY,patient_id TEXT NOT NULL REFERENCES patients(id) ON DELETE CASCADE,actor_id TEXT REFERENCES users(id) ON DELETE SET NULL,status TEXT NOT NULL DEFAULT 'registered',external_status TEXT NOT NULL DEFAULT 'not_configured',source TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS pain_reports (id TEXT PRIMARY KEY,patient_id TEXT NOT NULL REFERENCES patients(id) ON DELETE CASCADE,region TEXT NOT NULL,side TEXT NOT NULL,kind TEXT NOT NULL,intensity TEXT NOT NULL,since TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '',source TEXT NOT NULL,created_at TEXT NOT NULL,external_status TEXT NOT NULL DEFAULT 'not_configured');
CREATE TABLE IF NOT EXISTS devices (id TEXT PRIMARY KEY,patient_id TEXT NOT NULL REFERENCES patients(id) ON DELETE CASCADE,name TEXT NOT NULL,last_sync TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('web','watch')),UNIQUE(patient_id,name));
CREATE TABLE IF NOT EXISTS preferences (patient_id TEXT PRIMARY KEY REFERENCES patients(id) ON DELETE CASCADE,medication INTEGER NOT NULL DEFAULT 1,appointment INTEGER NOT NULL DEFAULT 1,pain INTEGER NOT NULL DEFAULT 1,sos INTEGER NOT NULL DEFAULT 1,missing INTEGER NOT NULL DEFAULT 1,grace_minutes INTEGER NOT NULL DEFAULT 30);
CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY,patient_id TEXT NOT NULL REFERENCES patients(id) ON DELETE CASCADE,actor_id TEXT REFERENCES users(id) ON DELETE SET NULL,type TEXT NOT NULL,title TEXT NOT NULL,details TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY,patient_id TEXT NOT NULL REFERENCES patients(id) ON DELETE CASCADE,kind TEXT NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,created_at TEXT NOT NULL,dedupe_key TEXT UNIQUE);
CREATE TABLE IF NOT EXISTS notification_reads (notification_id TEXT NOT NULL REFERENCES notifications(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(notification_id,user_id));
CREATE TABLE IF NOT EXISTS interactions (id TEXT PRIMARY KEY,patient_id TEXT NOT NULL REFERENCES patients(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,question TEXT NOT NULL,answer TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS mutations (patient_id TEXT NOT NULL REFERENCES patients(id) ON DELETE CASCADE,action_id TEXT NOT NULL,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,result TEXT NOT NULL,PRIMARY KEY(patient_id,action_id));
CREATE INDEX IF NOT EXISTS idx_med_patient ON medications(patient_id);
CREATE INDEX IF NOT EXISTS idx_appt_date ON appointments(patient_id,date);
CREATE INDEX IF NOT EXISTS idx_events_patient ON events(patient_id,created_at);
CREATE INDEX IF NOT EXISTS idx_notifications_patient ON notifications(patient_id,created_at);
CREATE INDEX IF NOT EXISTS idx_confirm_day ON confirmations(patient_id,day);
